{"cmd":"python - <<'PY'
import json
from pathlib import Path
import re
brief = Path('/app/benchmark/source_brief.md').read_text()
# Extract quant table rows by regex
lines = brief.splitlines()
start = None
for i,l in enumerate(lines):
    if l.strip().startswith('| Model | MMLU'):
        start=i
        break
rows=[]
if start is not None:
    for l in lines[start+2:]:
        if not l.strip().startswith('|'):
            break
        parts=[p.strip() for p in l.strip().strip('|').split('|')]
        if len(parts)==5:
            rows.append(parts)
print('rows',len(rows))
for r in rows:
    print(r[0])
PY"}

